"""Create a source-only experimental snapshot; never packages runtime/config."""
from pathlib import Path
import json
import zipfile

ROOT=Path(__file__).resolve().parents[1]

SOURCE_EXTENSIONS = {'.py', '.md', '.sh', '.txt', '.js', '.css', '.html'}
ASSET_EXTENSIONS = {'.urdf', '.stl', '.obj', '.json'}
# Recorded experiment reports stay local; synthetic test data is generated by code.
SAFE_FIXTURES = set()
EXCLUDED_PARTS = {'__pycache__', '.runtime', '.git', '.pytest_cache', 'artifacts',
                  'screenshots', 'browser-artifacts', '.venv', '.venv311'}


def include_source(path):
    relative = path.relative_to(ROOT)
    if path.is_symlink() or any(part in EXCLUDED_PARTS for part in relative.parts):
        return False
    if relative.parts[:2] == ('tests', 'fixtures'):
        return len(relative.parts) == 3 and path.name in SAFE_FIXTURES
    if relative.parts[:2] == ('embodied_arm', 'assets'):
        return path.suffix in SOURCE_EXTENSIONS | ASSET_EXTENSIONS or path.name == 'LICENSE'
    return path.suffix in SOURCE_EXTENSIONS or path.name == '.gitignore'


def package(destination):
    destination=Path(destination)
    roots=('tests','embodied_arm','experiments','tools','docs','scripts')
    files=[ROOT/name for name in ('README.md','requirements.txt','pyproject.toml','.gitignore') if (ROOT/name).is_file()]
    example=ROOT/'config/provider.example.json'
    if example.is_symlink():
        raise ValueError('Unsafe configuration template path')
    if example.exists():
        data=json.loads(example.read_text())
        if not isinstance(data,dict) or set(data)-{'provider','endpoint','model','api_key','min_confidence','timeout'}:
            raise ValueError('Unexpected configuration template fields')
        if data.get('api_key') not in ('',None):raise ValueError('Example contains nonempty credential')
        files.append(example)
    versioned=ROOT/'config/provider-v2.example.json'
    if versioned.is_symlink():raise ValueError('Unsafe configuration template path')
    if versioned.exists():
        data=json.loads(versioned.read_text())
        if not isinstance(data,dict) or set(data)!={'schema_version','brain','cerebellum'} or data['schema_version']!=2:
            raise ValueError('Unexpected versioned configuration template fields')
        for component in ('brain','cerebellum'):
            group=data[component]
            if not isinstance(group,dict) or set(group)-{'provider','base_url','model','api_key','timeout','min_confidence'}:
                raise ValueError('Unexpected provider template fields')
            if group.get('api_key') not in ('',None):raise ValueError('Example contains nonempty credential')
        files.append(versioned)
    for name in roots:
        directory=ROOT/name
        if directory.exists():files.extend(p for p in directory.rglob('*') if p.is_file() and include_source(p))
    if any(p.is_symlink() or not p.is_relative_to(ROOT) for p in files):raise ValueError('Unsafe package path')
    destination.parent.mkdir(parents=True,exist_ok=True)
    with zipfile.ZipFile(destination,'w',zipfile.ZIP_DEFLATED) as archive:
        for path in sorted(set(files)):archive.write(path,Path('jev-arm-sandbox')/path.relative_to(ROOT))
    return len(set(files)),destination.stat().st_size

if __name__=='__main__':
    import argparse
    parser=argparse.ArgumentParser();parser.add_argument('destination');args=parser.parse_args()
    count,size=package(args.destination);print(f'{count} source files; {size} bytes')
